/**
 * STUDIO PRODUCTION LANE DOCTRINE — who makes the picture (LOCKED 2026-09-15).
 *
 * Owner correction, 2026-09-15: the Machine's engineer is responsible for
 * engineering, orchestration, integration, QA, and production reliability. It is
 * not responsible for hand-building customer-facing visual art, and it must not
 * simulate premium imagery with hand-authored vector scenes. Original visual
 * material is generated by an image provider; the Studio composition and fact
 * layers finish the deliverable.
 *
 * The lanes below are not interchangeable. Each names the asset path a service
 * must start from, because the failure mode is always the same: starting from the
 * wrong asset and then rescuing it with manual surgery.
 *
 * Authority: `docs/studio-production-lane-doctrine-v1-locked.md`
 */

import { studioAutonomousProductionLoopV1 } from "./studio-autonomous-production-loop-v1";

export const STUDIO_PRODUCTION_LANE_DOCTRINE_PACKAGE_ID =
  "STUDIO-PRODUCTION-LANE-DOCTRINE-1" as const;

export type ProductionLaneId =
  | "static_creative"
  | "reusable_character"
  | "motion_character";

export type ProductionLane = {
  id: ProductionLaneId;
  label: string;
  /** Where the visual asset is allowed to come from. */
  assetOrigin: string;
  /** What the Studio's own layers still own, regardless of who made the picture. */
  studioOwns: readonly string[];
  /** Named ways this lane has failed or would fail. Not hypothetical. */
  forbidden: readonly string[];
  certified: boolean;
};

export const STUDIO_PRODUCTION_LANES_V1: readonly ProductionLane[] = [
  {
    id: "static_creative",
    label: "Static creative — flyers, posters, social stills",
    assetOrigin:
      "Image generation may create the final visual asset, or the customer supplies licensed imagery.",
    studioOwns: [
      "layout and layout family",
      "crop and focal positioning",
      "typography and hierarchy",
      "layering, masks, transparency",
      "exact customer facts, offer, CTA, contact route",
      "print geometry and export",
      "QA of the finished artifact",
    ],
    forbidden: [
      "hand-authored vector scenes standing in for photographic art",
      "customer facts baked into the generated pixels",
      "tiling several generations into one subject to reach print size",
    ],
    certified: false,
  },
  {
    id: "reusable_character",
    label: "Reusable character or mascot",
    assetOrigin:
      "A locked character master plus a consistency package. Every appearance derives from that master.",
    studioOwns: [
      "pose and scene selection within the approved wardrobe",
      "composition and fact layers",
      "consistency verification against the master",
    ],
    forbidden: [
      "regenerating a 'similar' character per scene and hoping for consistency",
      "treating one lucky generation as the master without a consistency package",
    ],
    certified: false,
  },
  {
    id: "motion_character",
    label: "Motion character",
    assetOrigin:
      "A certified motion-ready asset on a rigging path. Motion is planned before the asset exists.",
    studioOwns: ["scene direction", "timing", "audio sync", "export"],
    forbidden: [
      "creating a static character and later assembling eyes, mouth, glasses, limbs, or overlays to force animation",
      "frame-by-frame manual asset surgery to fake a rig",
    ],
    certified: false,
  },
];

/**
 * A lane that needs the Owner to rescue it is not a lane. The attempt budget is
 * the existing internal production budget — this doctrine does not invent a
 * second number, it states what exceeding it means.
 */
export const PRODUCTION_LANE_CERTIFICATION_RULE_V1 = {
  maxSeriousAttempts: studioAutonomousProductionLoopV1.maxInternalProductionAttempts,
  /** Signals that disqualify a lane rather than justifying another attempt. */
  disqualifyingSignals: [
    "manual puzzle-piece alignment of separately produced parts",
    "repeated asset surgery to make a delivered asset usable",
    "more serious production attempts than the internal budget allows",
    "the Owner having to finish or rescue the artifact",
  ],
  /** The verdict when a signal fires. Not 'try harder'. */
  verdict: "LANE_NOT_CERTIFIED" as const,
  ownerRescueIsNotAProductionPath: true as const,
} as const;

export const studioProductionLaneDoctrineV1 = {
  packageId: STUDIO_PRODUCTION_LANE_DOCTRINE_PACKAGE_ID,
  schemaVersion: 1 as const,
  lockedAt: "2026-09-15" as const,
  lanes: STUDIO_PRODUCTION_LANES_V1,
  certificationRule: PRODUCTION_LANE_CERTIFICATION_RULE_V1,
  engineerResponsibilities: [
    "engineering",
    "orchestration",
    "integration",
    "QA",
    "production reliability",
  ] as const,
  engineerMustNot: [
    "hand-build final customer-facing hero art",
    "simulate premium imagery with flat vector scenes",
  ] as const,
} as const;

export function productionLane(id: ProductionLaneId): ProductionLane {
  const lane = STUDIO_PRODUCTION_LANES_V1.find((candidate) => candidate.id === id);
  if (!lane) throw new Error(`UNKNOWN_PRODUCTION_LANE:${id}`);
  return lane;
}

export type StudioProductionLaneDoctrine = typeof studioProductionLaneDoctrineV1;
